import json,pathlib
root=pathlib.Path(__file__).resolve().parent
chunks={r['Sequence']:r for r in json.loads((root/'baseline-chunks-from-langfuse.json').read_text())}
out=[]
def add(id,b,task,context,start,end=None,**kw):
 text=chunks[b]['Text'];i=text.index(start);q=text[i:] if end is None else text[i:text.index(end,i)+len(end)]
 chapter=('CHAPTER 1' if 4<=b<=10 else 'CHAPTER 2' if 11<=b<=21 else 'CHAPTER 3' if 22<=b<=23 else 'CHAPTER 4' if 24<=b<=31 else 'CHAPTER 5' if 32<=b<=38 else None)
 out.append(dict(id=id,block=b,task=task,context=context,chapter=chapter,quotes=[q],context_evidence=[chunks[b]['Section'],start],**kw))
